INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-direccion-tecnica', 'direccion-tecnica', 'Dirección Técnica', 'Dirección Técnica', 'Acompañamiento técnico permanente y representación ante los organismos.', 'La dirección técnica no es solo una firma. Es el respaldo técnico que sostiene las decisiones del día a día y la relación con los organismos.', 'Asumimos la dirección técnica de su planta o empresa: ordenamos las obligaciones, revisamos el sistema y acompañamos inspecciones, auditorías y desvíos con criterio técnico.', 'La dirección técnica es la figura que respalda técnicamente a la empresa frente a los organismos y dentro de la propia operación. Cuando se asume en serio, ordena obligaciones, prioriza brechas y da criterio para decidir.\r\n\r\n## Qué incluye\r\n\r\n- Revisión del sistema vigente y de las obligaciones aplicables a su rubro.\r\n- Acompañamiento técnico permanente para consultas de producto, proceso y cumplimiento.\r\n- Preparación y acompañamiento en inspecciones y auditorías.\r\n- Seguimiento de desvíos, acciones correctivas y actualización documental.\r\n- Representación técnica ante los organismos cuando corresponde.\r\n\r\n## Cómo trabajamos\r\n\r\nEmpezamos con un diagnóstico del estado actual: qué está resuelto, qué falta y qué riesgos conviene atender primero. A partir de ahí definimos una rutina de seguimiento y un canal directo para las consultas del día a día.\r\n\r\nEl objetivo no es acumular documentación, sino que la empresa tenga una referencia técnica clara para sostener sus decisiones y sus plazos.', '[{\"title\":\"Diagnóstico y ordenamiento\",\"description\":\"Revisamos el sistema y priorizamos las brechas que más impactan.\"},{\"title\":\"Acompañamiento en inspecciones\",\"description\":\"Preparamos la visita y coordinamos con los organismos.\"},{\"title\":\"Seguimiento continuo\",\"description\":\"Informes, desvíos y actualización de obligaciones.\"}]', 'service-registro-productos', '/images/service-quality.webp', 'Revisión técnica en una planta alimentaria', 'users', '[\"Dirección técnica\"]', 'direccion tecnica responsable tecnico acompanamiento permanente organismos representacion auditoria inspeccion', 'Consultar', '/#contacto', 1, 'Dirección Técnica | Kaizen', 'Acompañamiento técnico permanente, representación ante organismos e inspecciones para empresas alimentarias.', 1);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-registro-productos', 'registro-de-productos', 'Registro de Productos', 'Registro de Productos', 'Registro de productos y empresas ante los organismos que correspondan.', 'Registrar no es solo presentar un formulario: es demostrar que el producto y la empresa cumplen lo que declaran.', 'Ordenamos el expediente, revisamos requisitos y acompañamos la presentación y el seguimiento del registro de empresa, local y producto, incluida la importación.', 'El registro de productos se apoya en tres capas distintas que la normativa mira por separado: la empresa, el local y el producto. Según el rubro, puede necesitar una, dos o las tres.\n\n## Qué incluye\n\n- Revisión de requisitos aplicables a su categoría de producto.\n- Ordenamiento del expediente y de la documentación de respaldo.\n- Presentación y seguimiento ante los organismos.\n- Registro de empresa, local y producto cuando corresponde.\n- Renovaciones y actualizaciones antes del vencimiento.\n- Acompañamiento en importación y exportación.\n\n## Cómo evitamos idas y vueltas\n\nLa mayoría de las demoras no vienen del organismo, sino de expedientes incompletos o inconsistentes. Revisamos la documentación antes de presentar y coordinamos el ida y vuelta para que el trámite avance sin sorpresas.', '[{\"title\":\"Expediente completo\",\"description\":\"Ordenamos formularios y respaldos antes de presentar.\"},{\"title\":\"Presentación y seguimiento\",\"description\":\"Gestionamos el trámite y su ida y vuelta con el organismo.\"},{\"title\":\"Renovaciones al día\",\"description\":\"Avisamos y preparamos las actualizaciones antes del vencimiento.\"}]', 'service-habilitacion-locales', '/images/service-regulatory.webp', 'Operario controlando una línea de procesamiento de alimentos', 'file', '[\"RUNAEV\",\"Registro\"]', 'registro productos runaev msp empresa local producto importacion exportacion certificado renovacion expediente', 'Consultar', '/#contacto', 1, 'Registro de Productos | Kaizen', 'Registro de empresa, local y producto, presentación y seguimiento ante los organismos.', 2);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-habilitacion-locales', 'habilitacion-de-locales', 'Habilitaciones', 'Habilitación de Locales', 'Habilitación de locales y acompañamiento en los trámites que dependen de terceros.', 'Habilitar un local es más simple cuando los requisitos se conocen antes de alquilar, reformar o abrir.', 'Definimos los requisitos según el rubro, revisamos el local antes de la inspección y coordinamos los trámites con los organismos y técnicos que correspondan.', 'La habilitación de un local depende del rubro, la actividad y la superficie. Lo que cambia es el alcance, no la lógica: primero se definen los requisitos, después se prepara el local y recién entonces se inspecciona.\n\n## Qué incluye\n\n- Definición de requisitos aplicables según actividad y rubro.\n- Revisión del local y de la documentación antes de la inspección.\n- Acompañamiento en la presentación ante el organismo.\n- Coordinación con Bomberos, SIME y otros técnicos habilitados cuando corresponde.\n- Seguimiento de observaciones hasta la resolución.\n\n## Qué hacemos y qué coordina un tercero\n\nKaizen acompaña el proceso y ordena la documentación técnica. La ejecución de instalaciones, planos y trámites que exigen firma de un profesional habilitado se coordina con terceros; nuestro rol es que todo llegue en orden a la inspección.', '[{\"title\":\"Requisitos por rubro\",\"description\":\"Definimos qué aplica según actividad y superficie.\"},{\"title\":\"Revisión previa\",\"description\":\"Verificamos el local y la documentación antes de la inspección.\"},{\"title\":\"Coordinación con terceros\",\"description\":\"Acompañamos Bomberos, SIME y técnicos habilitados.\"}]', 'service-registro-productos', '/images/hero-food-factory.webp', 'Local de elaboración de alimentos', 'building', '[\"Habilitación\"]', 'habilitacion locales local rubro planos bomberos sime inspeccion requisitos habilitacion comercial', 'Consultar', '/#contacto', 1, 'Habilitación de Locales | Kaizen', 'Requisitos, revisión previa y acompañamiento en la habilitación de locales alimentarios.', 3);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-labeling', 'rotulado-de-alimentos', 'Producto y procesos', 'Rotulado de alimentos', 'Información correcta y una presentación coherente con el producto real.', 'La etiqueta es la carta de presentación del producto y, también, una declaración técnica que tiene que poder respaldarse.', 'Revisamos declaraciones, ingredientes, alérgenos, información nutricional, imágenes y legibilidad. La etiqueta debe cumplir la norma y sostener exactamente lo que el producto es.', 'El rotulado combina cumplimiento legal y coherencia técnica. No alcanza con que los datos obligatorios estén: tienen que ser correctos, legibles y consistentes con lo que el producto realmente es.\n\n## Qué revisamos\n\n- Denominación, ingredientes y orden de la lista.\n- Información nutricional y porciones.\n- Alérgenos y declaraciones especiales, como “libre de gluten” u “orgánico”.\n- Imágenes y textos que puedan sugerir algo que el producto no tiene.\n- Legibilidad, tamaño de letra y ubicación de la información.\n\n## Cuándo conviene revisarlo\n\nAntes de imprimir. Un ajuste en el archivo digital es simple; reimprimir etiquetas, no. También conviene revisar el rótulo cuando cambia la formulación, el proveedor o una certificación que sostiene una declaración.', '[{\"title\":\"Revisión legal y técnica\",\"description\":\"Cada declaración tiene que poder sostenerse con respaldo.\"},{\"title\":\"Información nutricional\",\"description\":\"Cálculo, formato y coherencia con la formulación.\"},{\"title\":\"Imágenes y declaraciones\",\"description\":\"Que la etiqueta represente exactamente el producto.\"}]', 'service-safety', '/images/service-labeling.webp', 'Persona rotulando una caja con marcador', 'tag', '[\"Rotulado\"]', 'rotulado etiqueta etiquetas rotulo declaracion nutricional ingredientes alergenos gluten libre de gluten organicos organico informacion nutricional', 'Consultar', '/#contacto', 0, 'Rotulado de alimentos | Kaizen', 'Revisión de etiquetas, información nutricional, alérgenos y declaraciones para la industria alimentaria.', 4);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-safety', 'inocuidad-alimentaria', 'Producto y procesos', 'Inocuidad alimentaria', 'BPM, POES, HACCP y controles para prevenir peligros en los alimentos.', 'Inocuidad es prevenir: identificar peligros, controlarlos en la operación y dejar evidencia de que el control funciona.', 'Implementamos BPM, POES y HACCP, revisamos peligros, trazabilidad y controles. El foco está en prevenir y en poder demostrarlo con registros.', 'La inocuidad alimentaria se sostiene en tres capas que conviene distinguir: las buenas prácticas de manufactura (BPM), los procedimientos de saneamiento (POES) y el sistema HACCP. Cada una tiene un alcance distinto y las tres se complementan.\n\n## Qué incluye\n\n- Diagnóstico de la operación y de los peligros asociados al producto y al proceso.\n- Implementación de BPM y POES, con registros simples de mantener.\n- Desarrollo del plan HACCP: puntos críticos, límites y verificaciones.\n- Trazabilidad y control de proveedores.\n- Capacitación del equipo y preparación para auditorías.\n\n## Cómo se demuestra\n\nCon registros que reflejen la operación real. Un sistema de inocuidad no es un manual guardado: es lo que el equipo hace todos los días y puede mostrar cuando se lo revisan.', '[{\"title\":\"BPM y POES\",\"description\":\"Prácticas y saneamiento integrados a la operación real.\"},{\"title\":\"Plan HACCP\",\"description\":\"Peligros, puntos críticos y verificaciones documentadas.\"},{\"title\":\"Trazabilidad\",\"description\":\"Registros que permiten seguir el producto y responder.\"}]', 'service-quality', '/images/service-safety.webp', 'Operaria verificando productos en una planta alimentaria', 'shield', '[\"HACCP\",\"BPM\"]', 'inocuidad bpm poes haccp plagas trazabilidad control peligros capacitacion auditoria', 'Consultar', '/#contacto', 0, 'Inocuidad alimentaria | Kaizen', 'Implementación de BPM, POES y HACCP, trazabilidad y preparación para auditorías.', 5);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-ambiente-residuos', 'ambiente-y-residuos', 'Regulatorios', 'Ambiente y residuos', 'Declaraciones juradas, gestión de residuos y envases.', 'Las obligaciones ambientales no tienen la urgencia visible de una habilitación, pero se revisan en auditorías y conviene resolverlas en paralelo.', 'Acompañamos las obligaciones ambientales de la empresa: declaración jurada de residuos, planes de gestión, envases y documentación de seguimiento.', 'Las obligaciones ambientales suelen quedar postergadas porque no frenan la operación. Sin embargo, forman parte de lo que se revisa en una auditoría y de la documentación que la empresa debe poder mostrar.\n\n## Qué incluye\n\n- Declaración jurada de residuos y actualizaciones.\n- Plan de gestión de residuos y su seguimiento.\n- Gestión de envases y de los circuitos asociados.\n- Documentación de respaldo y coordinación con los organismos.\n- Integración con la habilitación del local y con el sistema de inocuidad.\n\n## Cómo lo ordenamos\n\nArmamos un calendario de obligaciones y dejamos el circuito documental funcionando. La idea es que, una vez resuelto, no vuelva a demandar tiempo cada vez que se acerca un vencimiento.', '[{\"title\":\"Declaración jurada\",\"description\":\"Preparamos y actualizamos la declaración de residuos.\"},{\"title\":\"Plan de gestión\",\"description\":\"Definimos el circuito y su documentación de seguimiento.\"},{\"title\":\"Envases y vencimientos\",\"description\":\"Ordenamos obligaciones y avisamos antes de cada plazo.\"}]', 'service-registro-productos', '/images/blog/blog-residuos.webp', 'Contenedores para la clasificación de residuos', 'leaf', '[\"Residuos\",\"Ambiente\"]', 'ambiente residuos declaracion jurada pgr envases gestion residuos plan ambiental', 'Consultar', '/#contacto', 0, 'Ambiente y residuos | Kaizen', 'Declaración jurada de residuos, planes de gestión, envases y seguimiento ambiental.', 6);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-latu-sigla-vehiculos', 'latu-sigla-y-vehiculos', 'Habilitaciones', 'LATU/SIGLA y vehículos', 'Gestiones ante LATU/SIGLA y habilitación de vehículos ante MGAP.', 'Los trámites de LATU/SIGLA y de vehículos tienen requisitos propios y conviene encararlos con la misma lógica que el resto de las habilitaciones.', 'Acompañamos los trámites ante LATU/SIGLA y la habilitación de vehículos de transporte de alimentos ante MGAP, con la documentación y el seguimiento que cada gestión requiere.', 'Además de los registros de producto y local, muchas empresas necesitan resolver gestiones específicas ante LATU/SIGLA y habilitar los vehículos que transportan alimentos ante MGAP.\n\n## LATU / SIGLA\n\nAcompañamos la presentación y el seguimiento de las gestiones que se realizan ante LATU/SIGLA, revisando antes la documentación y los requisitos aplicables a cada caso.\n\n## Vehículos y MGAP\n\nLa habilitación de vehículos para transporte de alimentos se gestiona ante MGAP. Revisamos las condiciones del vehículo, la documentación y el circuito de habilitación para que la presentación llegue completa.\n\n## Qué incluye\n\n- Revisión de requisitos según el tipo de gestión.\n- Ordenamiento de la documentación de respaldo.\n- Presentación y seguimiento ante LATU/SIGLA y MGAP.\n- Coordinación con las demás habilitaciones de la empresa.', '[{\"title\":\"LATU / SIGLA\",\"description\":\"Revisión, presentación y seguimiento de cada gestión.\"},{\"title\":\"Vehículos\",\"description\":\"Habilitación para transporte de alimentos ante MGAP.\"},{\"title\":\"Documentación en orden\",\"description\":\"Evitamos observaciones por expedientes incompletos.\"}]', 'service-registro-productos', '/images/blog/blog-importaciones.webp', 'Contenedores de carga en un puerto', 'globe', '[\"LATU\",\"SIGLA\",\"MGAP\"]', 'latu sigla vehiculos mgap transporte habilitacion vehiculo importacion exportacion camion', 'Consultar', '/#contacto', 0, 'LATU/SIGLA y vehículos | Kaizen', 'Gestiones ante LATU/SIGLA y habilitación de vehículos de transporte de alimentos ante MGAP.', 7);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-engineering', 'ingenieria-de-alimentos', 'Producto y procesos', 'Ingeniería de alimentos', 'Desarrollo, reformulación y mejora de productos y procesos alimentarios.', 'Desarrollar un producto es resolver, al mismo tiempo, la formulación, el proceso y la forma de demostrar que se puede repetir.', 'Trabajamos en formulación, vida útil, escalado y transferencia a planta. El objetivo es que el producto sea viable técnica y comercialmente, con un proceso reproducible y documentado.', 'Trabajamos en formulación, vida útil, escalado y transferencia a planta. El objetivo es que el producto sea viable técnica y comercialmente, con un proceso reproducible y documentado.\n\n## Qué incluye\n\n- Desarrollo y reformulación de productos.\n- Definición de proceso y parámetros críticos.\n- Estudios de vida útil y validaciones.\n- Escalado y transferencia a planta.\n- Documentación técnica del producto y del proceso.\n\n## Cómo lo encaramos\n\nPartimos de la idea comercial y la bajamos a formulación y proceso. Cada decisión se documenta para que la planta pueda repetir el resultado sin depender de la memoria de quien lo desarrolló.', '[{\"title\":\"Formulación\",\"description\":\"Desarrollo y reformulación con criterio técnico y comercial.\"},{\"title\":\"Vida útil\",\"description\":\"Estudios y validaciones para sostener la fecha declarada.\"},{\"title\":\"Escalado\",\"description\":\"Transferencia a planta con proceso reproducible.\"}]', 'service-quality', '/images/service-engineering.webp', 'Elaboración de quesos en una planta alimentaria', 'flask', '[\"Producto\",\"Proceso\"]', 'ingenieria alimentos desarrollo reformulacion producto proceso vida util escalado mermas formulacion', 'Consultar', '/#contacto', 0, 'Ingeniería de alimentos | Kaizen', 'Desarrollo, reformulación, vida útil y escalado de productos y procesos alimentarios.', 8);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-quality', 'calidad', 'Producto y procesos', 'Calidad', 'Sistemas, auditorías y herramientas para controlar y mejorar su operación.', 'Un sistema de calidad sirve cuando ayuda a decidir y a mejorar, no cuando termina archivado.', 'Diseñamos sistemas de gestión, auditorías internas, indicadores y tratamiento de desvíos. Buscamos controles útiles para la operación, no documentación de archivo.', 'Diseñamos sistemas de gestión, auditorías internas, indicadores y tratamiento de desvíos. Buscamos controles útiles para la operación, no documentación de archivo.\n\n## Qué incluye\n\n- Sistemas de gestión y documentación asociada.\n- Auditorías internas y preparación para auditorías externas.\n- Indicadores, reclamos y tratamiento de desvíos.\n- Evaluación y seguimiento de proveedores.\n- Mejora continua con acciones concretas.', '[{\"title\":\"Sistema de gestión\",\"description\":\"Documentación y controles alineados a la operación.\"},{\"title\":\"Auditorías\",\"description\":\"Preparación, ejecución y seguimiento de hallazgos.\"},{\"title\":\"Mejora continua\",\"description\":\"Indicadores y desvíos con acciones verificables.\"}]', 'service-safety', '/images/service-quality.webp', 'Control de calidad de envases de vidrio en una fábrica', 'badge', '[\"Calidad\"]', 'calidad sistema gestion auditoria auditorias proveedores indicadores no conformidad reclamos mejora continua', 'Consultar', '/#contacto', 0, 'Calidad | Kaizen', 'Sistemas de gestión, auditorías, indicadores y mejora continua para la industria alimentaria.', 9);
INSERT IGNORE INTO `services` (`id`, `slug`, `category`, `title`, `short_description`, `intro`, `description`, `content`, `highlights`, `related_service_id`, `image`, `image_alt`, `icon`, `labels`, `keywords`, `cta_label`, `cta_href`, `featured`, `seo_title`, `seo_description`, `sort_order`) VALUES ('service-documentation', 'gestion-documental', 'Producto y procesos', 'Gestión documental', 'Manuales, procedimientos y registros pensados para utilizarse.', 'La documentación funciona cuando el equipo puede usarla todos los días, no solo cuando aparece una auditoría.', 'Armamos manuales, procedimientos y registros simples de mantener. La documentación se diseña alrededor del proceso real para que el equipo pueda usarla todos los días.', 'Armamos manuales, procedimientos y registros simples de mantener. La documentación se diseña alrededor del proceso real para que el equipo pueda usarla todos los días.\n\n## Qué incluye\n\n- Manuales y procedimientos.\n- Registros operativos y de control.\n- Control de versiones y cambios.\n- Organización del expediente técnico.\n- Capacitación para el uso diario.', '[{\"title\":\"Manuales y procedimientos\",\"description\":\"Documentos claros, breves y aplicables.\"},{\"title\":\"Registros\",\"description\":\"Formatos que se completan en la operación real.\"},{\"title\":\"Expediente ordenado\",\"description\":\"Versiones y respaldos listos para una revisión.\"}]', 'service-quality', '/images/service-documentation.webp', 'Documentos de control sobre una caja de packaging', 'folder', '[\"Documentación\"]', 'documental documentacion manuales procedimientos registros sistema expediente', 'Consultar', '/#contacto', 0, 'Gestión documental | Kaizen', 'Manuales, procedimientos y registros simples de mantener para empresas alimentarias.', 10);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-ambiente-1', 'service-ambiente-residuos', '¿Qué es la declaración jurada de residuos?', 'Es la declaración que presenta la empresa sobre los residuos que genera y su gestión. Requiere respaldo documental y actualizaciones periódicas.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-direccion-1', 'service-direccion-tecnica', '¿Qué implica asumir la dirección técnica?', 'Implica respaldar técnicamente a la empresa, ordenar sus obligaciones y acompañar las decisiones de producto, proceso y cumplimiento. No es solo una firma: supone seguimiento y criterio técnico.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-documentation-1', 'service-documentation', '¿Qué tipo de documentación se arma?', 'Manuales, procedimientos, registros operativos y de control, con control de versiones y organización del expediente técnico.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-engineering-1', 'service-engineering', '¿Qué se define antes de escalar un producto a planta?', 'Se documentan la formulación, los parámetros críticos del proceso y las condiciones que deben repetirse en cada lote, para que la transferencia no dependa de la memoria de quien lo desarrolló.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-global-1', NULL, '¿Trabajan con empresas de cualquier tamaño?', 'Sí. Acompañamos desde emprendimientos que están dando sus primeros pasos hasta plantas con operación consolidada. El alcance y la dedicación se ajustan a cada caso.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-habilitacion-1', 'service-habilitacion-locales', '¿Qué necesito para habilitar un local?', 'Depende del rubro, la actividad y la superficie. Primero definimos los requisitos aplicables, después revisamos el local y la documentación, y recién entonces se presenta la habilitación.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-inocuidad-1', 'service-safety', '¿Implementan BPM y HACCP desde cero?', 'Sí. Partimos de un diagnóstico de la operación, implementamos BPM y POES, y desarrollamos el plan HACCP con registros que el equipo pueda sostener.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-latu-1', 'service-latu-sigla-vehiculos', '¿Qué se gestiona ante LATU/SIGLA?', 'Depende del caso: pueden ser ensayos, certificaciones o gestiones específicas de producto. Revisamos qué aplica antes de presentar.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-quality-1', 'service-quality', '¿Qué incluye un sistema de calidad útil para la operación?', 'Documentación asociada, auditorías internas, indicadores, reclamos, tratamiento de desvíos y seguimiento de proveedores, con acciones de mejora concretas.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-registro-1', 'service-registro-productos', '¿Qué diferencia hay entre registrar la empresa, el local y el producto?', 'Son tres capas distintas. La empresa es el responsable; el local es el espacio físico; el producto se registra en sí mismo. Según el rubro puede necesitar una, dos o las tres.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-rotulado-1', 'service-labeling', '¿Qué revisan de una etiqueta?', 'Denominación, ingredientes, alérgenos, información nutricional, declaraciones, imágenes y legibilidad. También verificamos que cada declaración tenga respaldo técnico.', 1);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-ambiente-2', 'service-ambiente-residuos', '¿Cómo se relaciona con la habilitación del local?', 'Conviene resolverla en paralelo. Forma parte de la documentación que se revisa y evita observaciones cuando llega una auditoría o una inspección.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-direccion-2', 'service-direccion-tecnica', '¿Pueden representarnos ante una inspección o auditoría?', 'Sí. Preparamos la instancia, revisamos la documentación y acompañamos la visita. Después trabajamos sobre las observaciones hasta cerrarlas.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-documentation-2', 'service-documentation', '¿Cómo se logra que la documentación se use?', 'Se diseña alrededor del proceso real y se acompaña con capacitación para el uso diario, de modo que no quede archivada hasta una auditoría.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-engineering-2', 'service-engineering', '¿Los estudios de vida útil forman parte del trabajo?', 'Sí. El alcance incluye estudios de vida útil y validaciones, junto con la documentación técnica del producto y del proceso.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-global-2', NULL, '¿Pueden acompañar un trámite que ya está en curso?', 'Sí. Revisamos el expediente y el estado actual, ordenamos lo que falta y retomamos el seguimiento con el organismo.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-habilitacion-2', 'service-habilitacion-locales', '¿Kaizen hace los trámites de Bomberos y SIME?', 'Acompañamos y coordinamos esas gestiones. La ejecución de instalaciones y los trámites que exigen firma de un profesional habilitado se realizan con terceros; nuestro rol es que todo llegue en orden.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-inocuidad-2', 'service-safety', '¿Qué es POES y por qué importa?', 'Son los procedimientos de saneamiento: limpieza y desinfección, control de plagas y otros controles de higiene. Sostienen la base sobre la que se apoya el resto del sistema.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-latu-2', 'service-latu-sigla-vehiculos', '¿Qué trámites de vehículos cubren?', 'La habilitación de vehículos para transporte de alimentos ante MGAP, con revisión de condiciones y documentación.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-quality-2', 'service-quality', '¿Trabajan la preparación para auditorías externas?', 'Sí. El alcance incluye auditorías internas y preparación para auditorías externas, siempre con foco en controles que el equipo pueda sostener en el día a día.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-registro-2', 'service-registro-productos', '¿Cuánto demora un registro?', 'Depende del tipo de producto y de la carga del organismo. Lo que sí controlamos es que el expediente esté completo antes de presentarlo, para evitar demoras por observaciones.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-rotulado-2', 'service-labeling', '¿Pueden declarar “libre de gluten”?', 'Podemos revisar si la declaración corresponde y qué respaldo exige. La etiqueta tiene que poder sostenerse frente a un control, no solo verse bien.', 2);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-ambiente-3', 'service-ambiente-residuos', '¿Incluye la gestión de envases?', 'Sí. Ordenamos las obligaciones asociadas a envases y dejamos el circuito documental funcionando para los vencimientos.', 3);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-direccion-3', 'service-direccion-tecnica', '¿Con qué frecuencia hay seguimiento?', 'Depende de la operación y de las obligaciones de cada empresa. Definimos una rutina de seguimiento y un canal directo para consultas del día a día.', 3);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-global-3', NULL, '¿Trabajan en todo el país?', 'Sí. Nuestra base está en Montevideo, pero acompañamos empresas de todo Uruguay y coordinamos visitas a planta cuando el trabajo lo requiere.', 3);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-habilitacion-3', 'service-habilitacion-locales', '¿Pueden revisar un local antes de alquilarlo?', 'Sí, y es lo recomendable. Revisar el local antes de firmar evita tener que hacer reformas costosas después.', 3);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-inocuidad-3', 'service-safety', '¿Cómo se demuestra la trazabilidad?', 'Con registros que permitan seguir el producto desde la materia prima hasta la salida. Lo importante es que reflejen la operación real y se puedan revisar rápido.', 3);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-latu-3', 'service-latu-sigla-vehiculos', '¿También gestionan ante MGAP?', 'Sí. Acompañamos las gestiones ante MGAP que correspondan, incluida la habilitación de vehículos.', 3);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-registro-3', 'service-registro-productos', '¿Se ocupan de las renovaciones?', 'Sí. Llevamos un calendario de vencimientos y preparamos las actualizaciones antes de que el trámite se venza.', 3);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-rotulado-3', 'service-labeling', '¿Cada cuánto hay que actualizar el rótulo?', 'Cuando cambia la formulación, el proveedor, una certificación o la normativa aplicable. También conviene revisarlo antes de cada reimpresión.', 3);
INSERT IGNORE INTO `faqs` (`id`, `service_id`, `question`, `answer`, `sort_order`) VALUES ('faq-global-4', NULL, '¿Cómo empieza el trabajo?', 'Con una primera conversación técnica para entender su caso. A partir de ahí le indicamos qué información necesitamos y le proponemos un alcance con próximos pasos.', 4);
INSERT IGNORE INTO `posts` (`id`, `slug`, `title`, `tag`, `excerpt`, `content`, `cover_image`, `cover_alt`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('post-analisis', 'que-analizar-y-cada-cuanto-hacerlo', '¿Qué analizar y cada cuánto hacerlo?', 'Planes de análisis', 'No hay una tabla única: la frecuencia combina requisitos normativos y criterio técnico.', 'Esta es, quizás, la pregunta que genera más incertidumbre: no hay una tabla única que diga “su producto se analiza cada tanto”. Lo que sí existe es un criterio para llegar a esa frecuencia, que combina los requisitos normativos de su categoría de producto y el criterio técnico: qué tan sensible es ese producto a variaciones, y qué tan grave sería un desvío no detectado a tiempo.\n\nDos empresas con productos parecidos pueden tener planes de análisis distintos, y las dos estar perfectamente en regla. Si hoy no tiene claro qué analizar ni cada cuánto, no está solo: es exactamente el tipo de definición para la que conviene un técnico que conozca su producto, no solo la norma en abstracto.', '/images/blog/blog-analisis.webp', 'Análisis de laboratorio con microscopio', 1, '2026-09-08 12:00:00.000', '2026-09-08 12:00:00.000', '2026-09-08 12:00:00.000');
INSERT IGNORE INTO `posts` (`id`, `slug`, `title`, `tag`, `excerpt`, `content`, `cover_image`, `cover_alt`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('post-importaciones', 'antes-de-importar-que-revisar-del-producto', 'Antes de importar: ¿qué revisar del producto?', 'Importaciones', 'Origen, formulación, documentación y requisitos de ingreso. Revisarlo antes de comprar es, literalmente, gratis.', 'Traer un producto de afuera siempre tiene ese momento de “ojalá no se trabe en la aduana”. Y la verdad es que la mayoría de las trabas se evitan revisando cuatro cosas antes de que el contenedor salga del puerto de origen: origen, formulación, documentación y requisitos de ingreso puntuales de Uruguay.\n\nLo que vemos seguido es que estas cuatro cosas se revisan recién cuando el producto ya está en camino, y ahí cualquier ajuste sale más caro y más lento. Revisarlas antes de comprar o de cerrar el contrato con el proveedor es, literalmente, gratis.\n\nNo hace falta ser especialista en comercio exterior para hacer esta revisión. Hace falta saber qué preguntar, y a eso nos dedicamos: a acompañar esa revisión antes de que el producto esté en un barco, no después.', '/images/blog/blog-importaciones.webp', 'Contenedores de carga apilados en un puerto', 1, '2026-10-06 12:00:00.000', '2026-10-06 12:00:00.000', '2026-10-06 12:00:00.000');
INSERT IGNORE INTO `posts` (`id`, `slug`, `title`, `tag`, `excerpt`, `content`, `cover_image`, `cover_alt`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('post-organicos', 'organicos-una-declaracion-que-necesita-respaldo', 'Orgánicos: una declaración que necesita respaldo.', 'Productos orgánicos', 'Documentación, certificación vigente y coherencia del rotulado son las tres patas.', 'Escribir “orgánico” en una etiqueta es fácil. Sostener esa palabra frente a un control, no tanto, porque no es un adjetivo más: es una declaración que la normativa exige poder respaldar en cualquier momento.\n\nEse respaldo tiene tres patas: documentación que acredite el origen orgánico del producto, certificación vigente emitida por quien corresponda, y coherencia del rotulado, para que la etiqueta diga exactamente lo que la certificación cubre.\n\nEl error más común no es la mala fe, es el desfasaje: una certificación que vence, un proveedor que cambia, un rótulo que no se actualiza al mismo ritmo. Si su producto se apoya en esta palabra para venderse, vale la pena revisar una vez al año que las tres patas sigan alineadas.', '/images/blog/blog-organicos.webp', 'Verduras frescas de producción orgánica', 1, '2026-08-25 12:00:00.000', '2026-08-25 12:00:00.000', '2026-08-25 12:00:00.000');
INSERT IGNORE INTO `posts` (`id`, `slug`, `title`, `tag`, `excerpt`, `content`, `cover_image`, `cover_alt`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('post-residuos', 'residuos-no-perder-de-vista-las-obligaciones', 'Residuos: no perder de vista las obligaciones.', 'Ambiente y residuos', 'Declaración jurada, plan de gestión y documentación de seguimiento.', 'De todos los trámites, este es el que más se posterga, no porque sea complicado, sino porque no tiene la urgencia visible de una habilitación o un registro de producto. Y sin embargo, es parte de lo que se revisa en cualquier auditoría.\n\nLo que la normativa pide, en general, se resume en una declaración jurada de residuos, un plan de gestión y la documentación de seguimiento que respalde ambos puntos en el tiempo.\n\nLa buena noticia es que, una vez que este circuito queda armado, no vuelve a demandar tiempo. Nuestra recomendación es simple: resolverlo en paralelo con la habilitación del local, no como un trámite aparte.', '/images/blog/blog-residuos.webp', 'Contenedores para la clasificación de residuos', 1, '2026-08-11 12:00:00.000', '2026-08-11 12:00:00.000', '2026-08-11 12:00:00.000');
INSERT IGNORE INTO `posts` (`id`, `slug`, `title`, `tag`, `excerpt`, `content`, `cover_image`, `cover_alt`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('post-rotulado', 'su-etiqueta-dice-mucho-mas-que-los-datos-obligatorios', 'Su etiqueta dice mucho más que los datos obligatorios.', 'Rotulado', 'Texto, imágenes y diseño tienen que ser coherentes con lo que el producto realmente es.', 'Piense en la etiqueta como la carta de presentación de su producto: es lo primero, y a veces lo único, que el cliente lee antes de decidir. El rótulo tiene que ser coherente en tres planos a la vez: el texto, que declare exactamente lo que el producto es; las imágenes, que no sugieran algo que el producto no tiene; y el diseño, que sea legible y no esconda información relevante.\n\nUn ejemplo típico: una foto de fruta fresca en un producto que solo lleva saborizante. Ese tipo de detalle es justamente lo que un control revisa con más atención. La buena noticia es que esto se resuelve una sola vez, bien, y evita el ida y vuelta de reimprimir etiquetas. Nosotros revisamos el rótulo completo antes de que se mande a imprimir.', '/images/blog/blog-rotulado.webp', 'Etiqueta nutricional de un producto envasado', 1, '2026-09-22 12:00:00.000', '2026-09-22 12:00:00.000', '2026-09-22 12:00:00.000');
INSERT IGNORE INTO `posts` (`id`, `slug`, `title`, `tag`, `excerpt`, `content`, `cover_image`, `cover_alt`, `published`, `published_at`, `created_at`, `updated_at`) VALUES ('post-runaev', 'empresa-local-producto-que-necesita-habilitar', 'Empresa, local y producto: ¿qué necesita habilitar?', 'RUNAEV', 'Son tres capas distintas y la confusión más común es pensar que con habilitar el local ya está todo resuelto.', 'Si alguna vez preguntó “¿qué tengo que habilitar?” y le devolvieron una lista interminable de siglas, no es solo a usted. Es de las preguntas que más nos hacen, y tiene una respuesta más simple de lo que parece.\n\nEn la práctica, hay tres cosas distintas que la normativa mira por separado: la empresa, como responsable de lo que produce o vende; el local, el espacio físico donde elabora, almacena o atiende; y el producto, que se registra en sí mismo, más allá de dónde se fabrique. La confusión más común es pensar que habilitando el local ya está todo resuelto. No es así: son trámites que corren en paralelo, y según su rubro puede necesitar uno, dos o los tres.\n\nSi recién está empezando, la buena noticia es que no hace falta resolverlo todo el primer día. Lo que sí ayuda es entender desde el principio cuáles de los tres le aplican. En Kaizen empezamos por ahí en cada primera consulta: separamos su caso en estas tres capas antes de hablar de plazos o de papeles.', '/images/blog/blog-starbucks.webp', 'Fachada de un local de Starbucks', 1, '2026-10-20 12:00:00.000', '2026-10-20 12:00:00.000', '2026-10-20 12:00:00.000');
